<script setup lang="ts">import { computed } from 'vue';import { usePhrasesStore } from '../stores/phrases.store';const p=usePhrasesStore();const label=computed(()=>{const h=new Date().getHours();return h<12?'Il pensiero del mattino':h<18?'Il pensiero del giorno':'Il pensiero della sera'})</script><template><section class="phrase"><div class="eyebrow">{{label}}</div><p class="serif">{{p.current?.text || 'Un momento, per te.'}}</p><div class="phrase-actions"><button class="quiet-button" @click="p.next">Prossimo pensiero</button><button class="quiet-button" @click="p.random">Sorprendimi</button></div></section></template><style scoped>.phrase{text-align:center;max-width:860px;margin-inline:auto}.phrase p{font-size:clamp(1.35rem,1rem + 1.25vw,2.55rem);line-height:1.48;margin:1rem auto 1.1rem;text-wrap:balance}.phrase-actions{display:flex;justify-content:center;gap:.5rem}.phrase-actions .quiet-button{font-size:var(--font-xs);opacity:.78}@media(max-width:600px){.phrase p{font-size:clamp(1.2rem,5vw,1.65rem);line-height:1.5}.phrase-actions{display:none}}</style>
